125	/**
126	 * Guest balloon-driver floor: how low Proxmox may squeeze a VM's memory under
127	 * host pressure. Without this, every VM's `memory:` is treated as a hard
128	 * reservation, so a node's VMs can sum to well past its physical RAM with no
129	 * way to reclaim anything from an idle one — confirmed 2026-09-14 as a
130	 * contributing cause of a primary-node OOM crash (the killed VM had no
131	 * balloon floor set at all, alongside two others provisioned the same way).
132	 * This convention already existed by hand on most of the fleet's older VMs
133	 * (a 50% floor) — it just was never wired into provisioning itself, so it
134	 * quietly stopped covering anything created since. 1024MB minimum keeps a
135	 * small plan's floor from being squeezed low enough to starve the OS+game.
136	 */
137	function balloonFloorMB(memoryMB: number): number {
138	  return Math.max(1024, Math.round(memoryMB * 0.5));
139	}
