2237	/**
2238	 * A failed job's charge was just refunded to the wallet: reverse any partner
2239	 * commission earned on that charge's invoice with it (owner's rule, 2026-09-29 —
2240	 * a refund comes off the commission; voided if unpaid, netted off the next payout
2241	 * if already paid). The invoice id is carried on the job payload by the charge
2242	 * site (lib/disk-expand.ts, lib/dedicated-ip-purchase.ts, lib/resize.ts); a job
2243	 * queued before that existed has none and is skipped. Keyed per job, so a
2244	 * re-run can never reverse twice. Never throws.
2245	 */
2246	async function reverseCommissionForFailedJob(job: Job, invoiceId: unknown, cents: number, what: string) {
2247	  if (typeof invoiceId !== "string" || !invoiceId || cents <= 0) return;
2248	  await reverseCommissionSafely(`failed ${job.type} job=${job.id}`, () =>
2249	    reversePartnerCommissionForRefund({ invoiceId, refundCents: cents, key: `job:${job.id}`, reason: `refund: failed ${what}` }),
2250	  );
2251	}
