2253	/**
2254	 * Refund a per-server disk expansion that was paid for but never delivered.
2255	 *
2256	 * The DISK_EXPAND handler advances `Server.extraDiskGB` only AFTER the disk has
2257	 * really grown, so that field is the ground truth for "did the customer get what
2258	 * they paid for". We refund only when it never reached the job's target — which
2259	 * also keeps this safe against the partial-success case (disk grown, filesystem
2260	 * left for the customer to grow by hand): that path completes successfully, sets
2261	 * extraDiskGB, and is therefore never refunded.
2262	 *
2263	 * Idempotent per job via the reconcile audit marker.
2264	 */
2265	async function reconcileFailedDiskExpand(job: Job) {
2266	  const p = (job.payload ?? {}) as { prorateCents?: number; addGB?: number; targetExtraDiskGB?: number; invoiceId?: string };
2267	  const cents = p.prorateCents ?? 0;
2268	  if (cents <= 0 || !job.serverId) return;
2269	
2270	  const already = await db.auditLog.findFirst({
2271	    where: { action: "server.disk_expand.reconcile", detail: { contains: `job=${job.id}` } },
2272	  });
2273	  if (already) return;
2274	
2275	  const server = await db.server.findUnique({
2276	    where: { id: job.serverId },
2277	    select: { userId: true, hostname: true, extraDiskGB: true },
2278	  });
2279	  if (!server) return;
2280	
2281	  // The expansion actually landed (or a later one superseded it) — the customer
2282	  // has the storage, so the charge stands. Nothing to unwind.
2283	  const target = Number(p.targetExtraDiskGB ?? 0);
2284	  if (target > 0 && server.extraDiskGB >= target) return;
2285	
2286	  try {
2287	    await db.$transaction([
2288	      db.user.update({ where: { id: server.userId }, data: { balanceCents: { increment: cents } } }),
2289	      db.walletTransaction.create({
2290	        data: {
2291	          userId: server.userId,
2292	          amountCents: cents,
2293	          description: `Refund: failed storage expansion (+${p.addGB ?? "?"} GB) — ${server.hostname}`,
2294	        },
2295	      }),
2296	      db.notification.create({
2297	        data: {
2298	          userId: server.userId,
2299	          title: `Storage expansion failed on ${server.hostname} — refunded`,
2300	          body: `We couldn't add the storage, so $${(cents / 100).toFixed(2)} has been credited back to your wallet. Your server and its data are untouched.`,
2301	          href: `/dashboard/servers/${job.serverId}`,
2302	        },
2303	      }),
2304	    ]);
2305	    await db.auditLog.create({
2306	      data: {
2307	        userId: server.userId,
2308	        action: "server.disk_expand.reconcile",
2309	        detail: `job=${job.id} addGB=${p.addGB} cents=${cents}`,
2310	      },
2311	    });
2312	    await reverseCommissionForFailedJob(job, p.invoiceId, cents, "storage expansion");
2313	  } catch (e: any) {
2314	    await db.auditLog
2315	      .create({
2316	        data: {
2317	          userId: server.userId,
2318	          action: "server.disk_expand.reconcile.uncharged",
2319	          detail: `job=${job.id} cents=${cents} :: ${e?.message ?? e}`,
2320	        },
2321	      })
2322	      .catch(() => {});
2323	  }
2324	}
