2328	 * release any pool IP the failed run managed to claim — see the ROLLBACK
2329	 * SAFETY note on applyDedicatedIpPurchase (lib/dedicated-ip-purchase.ts) for
2330	 * why "charge" and "allocate" are two independently-failable steps.
2331	 *
2332	 * Ground truth is `server.dedicatedIp`, exactly like reconcileFailedDiskExpand
2333	 * uses `server.extraDiskGB`: if the server actually ended up with one (this run
2334	 * got far enough, or a later retry/attempt succeeded), the charge stands and
2335	 * there is nothing to unwind. Idempotent per job via the reconcile audit
2336	 * marker.
2337	 */
2338	async function reconcileFailedDedicatedIp(job: Job) {
2339	  const p = (job.payload ?? {}) as { prorateCents?: number; invoiceId?: string };
2340	  const cents = p.prorateCents ?? 0;
2341	  if (!job.serverId) return;
2342	
