2397	/**
2398	 * Reverse a money side-effect that a job committed up-front but never delivered.
2399	 * Server actions charge/credit the wallet before enqueuing the worker job (so the
2400	 * UI reflects the change immediately); if the job then fails terminally the money
2401	 * must be unwound or the customer is charged for a resize that never happened
2402	 * (up) or keeps a downgrade credit for hardware they still have (down).
2403	 * Idempotent per job: guarded by the RECONCILED audit marker so a re-run can't
2404	 * double-reverse.
2405	 */
2406	async function reconcileFailedJob(job: Job) {
2407	  if (job.type === "DISK_EXPAND") return reconcileFailedDiskExpand(job);
2408	  if (job.type === "ASSIGN_DEDICATED_IP") return reconcileFailedDedicatedIp(job);
2409	  if (job.type !== "RESIZE") return;
2410	  const p = (job.payload ?? {}) as { prorateCents?: number; direction?: "up" | "down"; invoiceId?: string };
2411	  const cents = p.prorateCents ?? 0;
2412	  if (cents <= 0 || !job.serverId) return;
2413	
2414	  // Idempotency: skip if we already reversed this exact job.
2415	  const already = await db.auditLog.findFirst({
2416	    where: { action: "server.resize.reconcile", detail: { contains: `job=${job.id}` } },
2417	  });
2418	  if (already) return;
2419	
2420	  const server = await db.server.findUnique({ where: { id: job.serverId }, select: { userId: true, hostname: true } });
2421	  if (!server) return;
2422	
2423	  try {
2424	    if (p.direction === "up") {
2425	      // Upgrade charge never delivered → refund the prorated charge.
2426	      await db.$transaction([
2427	        db.user.update({ where: { id: server.userId }, data: { balanceCents: { increment: cents } } }),
2428	        db.walletTransaction.create({
2429	          data: { userId: server.userId, amountCents: cents, description: `Refund: failed upgrade — ${server.hostname}` },
2430	        }),
2431	      ]);
2432	    } else if (p.direction === "down") {
2433	      // Downgrade credit was given but hardware unchanged → claw the credit back.
2434	      // Guarded so it can never drive the balance negative; if the customer already
2435	      // spent it, we log and leave it (best-effort — they keep a small windfall).
2436	      await db.$transaction(async (tx) => {
2437	        await debitWallet(tx, server.userId, cents);
2438	        await tx.walletTransaction.create({
2439	          data: { userId: server.userId, amountCents: -cents, description: `Reversed downgrade credit (resize failed) — ${server.hostname}` },
2440	        });
2441	      });
2442	    }
2443	    await db.auditLog.create({
2444	      data: { userId: server.userId, action: "server.resize.reconcile", detail: `job=${job.id} dir=${p.direction} cents=${cents}` },
2445	    });
2446	    // Only an UPGRADE charge was a commissionable sale that is now refunded; a
2447	    // down-reversal claws back a credit, which never earned commission.
2448	    if (p.direction === "up") await reverseCommissionForFailedJob(job, p.invoiceId, cents, "upgrade");
2449	  } catch (e: any) {
2450	    // InsufficientBalanceError on a down-reversal is expected/acceptable; record it.
2451	    await db.auditLog.create({
2452	      data: { userId: server.userId, action: "server.resize.reconcile.uncharged", detail: `job=${job.id} dir=${p.direction} cents=${cents} :: ${e?.message ?? e}` },
2453	    }).catch(() => {});
2454	  }
2455	}
