2457	async function runJob(job: Job) {
2458	  // The job is already atomically claimed (status RUNNING, attempts incremented)
2459	  // by the loop's compare-and-swap before we get here — see the CAS in main().
2460	  console.log(`[worker] job ${job.id} ${job.type} server=${job.serverId}`);
2461	  try {
2462	    await handlers[job.type](job);
2463	    // Clear any error left over from an earlier failed attempt of THIS job. Without
2464	    // this, a job that failed once (error persisted, status QUEUED for retry) and
2465	    // then succeeded on a later attempt ends up DONE with a stale, misleading error
2466	    // still attached — indistinguishable from an actual silent failure to anyone
2467	    // reading Job.error (confirmed: a real PROVISION did exactly this today).

2467	    // reading Job.error (confirmed: a real PROVISION did exactly this today).
2468	    await db.job.update({ where: { id: job.id }, data: { status: "DONE", error: null } });
2469	    console.log(`[worker] job ${job.id} DONE`);
2470	  } catch (e: any) {
2471	    let error = `${e?.message ?? e}${e?.body ? ` :: ${e.body}` : ""}`;
2472	    // Defense in depth: a child process (e.g. `sshpass -p <rootPassword> …`) can
2473	    // leak the server's root password into the thrown message. Redact it before
2474	    // it is persisted to Job.error. Redact BEFORE slicing so a truncation can't
2475	    // sever the match. Best-effort — never let redaction lookup fail the job path.
2476	    if (job.serverId) {
2477	      try {
