let lastVmRecoverySweep = 0;

/**
 * CONCURRENT JOB SCHEDULING — the core of this file's job-processing model.
 *
 * `active` tracks every job this process currently has RUNNING: job id ->
 * its in-flight promise and the serverId it targets (null for jobs with no
 * server, e.g. SYNC_FORWARDS/SYNC_FIREWALL/STAGING_CONTROL). It is the
 * single source of truth the scheduler below uses for two different jobs:
 *
 *   1. Concurrency cap — `active.size` is how many slots are busy;
 *      `WORKER_CONCURRENCY - active.size` is how many new jobs may be
 *      claimed this tick. A slow job (e.g. a 20-minute PROVISION) just
 *      occupies one entry in this map for a long time; it never prevents
 *      other entries from being added/removed, so unrelated jobs are never
 *      blocked by it (requirement: a stuck job must not steal others'
 *      slots).
 *
 *   2. Per-server ordering — before claiming a QUEUED job, the scheduler
 *      refuses to claim it if `active` already holds a RUNNING job for the
 *      same serverId. This is what stops a PROVISION and a later DELETE
 *      for the same server from ever running concurrently or out of order:
 *      the DELETE simply stays QUEUED (re-checked every tick) until the
 *      PROVISION's promise settles and its entry is removed.
 *
 * WHY IN-PROCESS RATHER THAN A DB QUERY: this file's own module comment
 * states there is exactly ONE worker process for the whole platform
 * (systemd unit `nxeon-worker`), and `reapStuckJobs()` above runs once at
 * startup — before this loop claims anything — to clear out any RUNNING
 * row left over from a previous process. Given both of those, every row
 * this process ever sees with status RUNNING is a job THIS process itself
 * claimed via the CAS below, so `active` and "which serverIds have a
 * RUNNING job in the DB" are always the same set — checking the local Map
 * is exactly as correct as re-querying the DB for it, and far cheaper
 * (zero extra round-trips on the hot path). It also sidesteps a subtler
 * bug a DB-only check would have: two QUEUED jobs for the same serverId
 * both present in the SAME claim batch could otherwise both pass an
 * "is there already a RUNNING job for this serverId?" query (neither is
 * RUNNING yet) and both get claimed together — the loop below closes that
 * window by adding a claimed job's serverId to a same-tick lock set
 * immediately, synchronously, before even considering the next candidate.
 *
 * The atomic CAS (`updateMany` on {id, status:"QUEUED"} -> RUNNING,
 * count===1 wins) is kept EXACTLY as it was — this per-server gate runs
 * strictly before it, as an extra filter on which candidates are even
 * attempted, and never replaces it. If this service is ever split into
 * multiple worker processes/replicas, this in-process map stops being
 * sufficient on its own and the per-server check must move to a DB-backed
 * mechanism instead (e.g. querying for an existing RUNNING job with the
 * same serverId inside the same transaction as the CAS, or a Postgres
 * advisory lock keyed on serverId like lib/job-guard.ts already uses for
 * the enqueue-time "one in-flight job per server" guard those callers
 * rely on — note that guard is a separate, complementary safeguard on the
 * ENQUEUE side; this scheduler does not depend on it and enforces the same
 * invariant independently on the CLAIM side, so a gap or bug in one layer
 * doesn't compromise the other).
 */
const active = new Map<string, { promise: Promise<void>; serverId: string | null }>();
const CLAIM_BATCH_SIZE = Math.max(WORKER_CONCURRENCY * 5, 25);

/** Run a claimed job, always freeing its `active` slot when it settles. */
function launch(job: Job) {
  const p = runJob(job)
    .catch((e) => {
      // runJob already catches and records handler errors internally; this
      // only guards against something truly unexpected (e.g. a DB error in
      // its own catch-path) so it can never become an unhandled rejection
      // that crashes the whole worker process out from under every other
      // concurrently-running job.
      console.error(`[worker] job ${job.id} threw outside its own error handling`, e);
    })
    .finally(() => {
      active.delete(job.id);
    });
  active.set(job.id, { promise: p, serverId: job.serverId });
}

