input.old_string:
  // Fetch more candidates than we have free slots for: some may be
  // filtered out below because their serverId already has a job
  // RUNNING, so a plain `take: freeSlots` could under-claim even when
  // plenty of runnable work exists for OTHER servers.
  const candidates = await db.job.findMany({
    where: { status: "QUEUED" },
    orderBy: { createdAt: "asc" },
    take: CLAIM_BATCH_SIZE,
  });
  // Same-tick lock set: seeded with every serverId already RUNNING, and
  // grown as this tick claims more — see the long comment above `active`
  // for why this closes the "two QUEUED jobs for the same server in one
  // batch" race that a DB-only check could miss.
  const lockedServerIds = new Set<string>();
  for (const a of active.values()) if (a.serverId) lockedServerIds.add(a.serverId);

  for (const candidate of candidates) {
    if (claimedThisTick >= freeSlots) break;
    if (candidate.serverId && lockedServerIds.has(candidate.serverId)) {
      // Another job for this server is already RUNNING (or was claimed
      // earlier in this same tick) — leave it QUEUED. It will be
      // re-considered on a later tick once that job's slot frees, so
      // ordering relative to that job is preserved exactly.
      continue;
    }
    // Atomic claim: only the caller whose updateMany matches the still-
    // QUEUED row wins. If count===0 it was already taken (e.g. a retry
    // path, or in principle another worker) between our read above and
    // now — skip and move on to the next candidate rather than stalling
    // the whole tick on one lost race.
    const claim = await db.job.updateMany({
      where: { id: candidate.id, status: "QUEUED" },
      data: { status: "RUNNING", attempts: { increment: 1 } },
    });
    if (claim.count !== 1) continue;
    const claimed = await db.job.findUnique({ where: { id: candidate.id } });
    if (!claimed) continue;
    if (claimed.serverId) lockedServerIds.add(claimed.serverId);
    claimedThisTick++;
    console.log(
      `[worker] job ${claimed.id} ${claimed.type} server=${claimed.serverId} claimed (${active.size + 1}/${WORKER_CONCURRENCY} slots busy)`
    );
    launch(claimed);
  }
}

