// Standalone, throwaway verification of the NEW claim/ordering scheduler
// logic added to worker/index.ts's main() loop. Does NOT import worker/index.ts
// (that file's module body ends with `main()`, which would start the REAL
// worker loop against the REAL prod DB and run REAL Proxmox/SSH handlers —
// far too dangerous to import for a test). Instead this reimplements the
// exact same algorithm standalone (lockKeyFor / active Map / claim-batch /
// per-lock-key skip / launch) and exercises it against the REAL Postgres DB
// (same connection as the app, via the symlinked .env) so the atomic CAS is
// tested for real, but against fully throwaway data:
//   - a handful of new, disposable Server rows (needed only to satisfy the
//     real Job.serverId -> Server(id) foreign key constraint — confirmed via
//     `Job_serverId_fkey ... REFERENCES "Server"(id)`), clearly marked with a
//     "zzz-concurrency-test-" hostname prefix and referencing EXISTING
//     unrelated User/Plan/OsTemplate rows only as FK targets (never modified)
//   - Job rows for those fake servers only
//   - a fake `runJob` that never touches handlers/Proxmox/SSH — it just marks
//     RUNNING->DONE after a short simulated delay, while instrumenting
//     concurrency/ordering for the assertions below
// Everything this script creates is deleted at the end, in a finally block.
import { PrismaClient } from "@prisma/client";

const db = new PrismaClient();
const TEST_TAG = `zzz-concurrency-test-${Date.now()}`;
const CONCURRENCY = 3; // small, deliberately, so violations are easy to see
const POLL_MS = 50; // fast polling so the test finishes quickly

function lockKeyFor(job) {
  return job.serverId ?? `type:${job.type}`;
}

async function main() {
  console.log(`[test] tag=${TEST_TAG}`);

  // ---- Seed throwaway fixtures ---------------------------------------
  const user = await db.user.findFirst({ select: { id: true } });
  const plan = await db.plan.findFirst({ select: { id: true } });
  const osTemplate = await db.osTemplate.findFirst({ select: { id: true } });
  if (!user || !plan || !osTemplate) throw new Error("no existing user/plan/osTemplate found to reference as FK targets");

  // 4 servers that should be able to run fully in parallel.
  const parallelServers = [];
  for (let i = 0; i < 4; i++) {
    const s = await db.server.create({
      data: {
        name: `${TEST_TAG}-parallel-${i}`,
        hostname: `${TEST_TAG}-parallel-${i}`,
        userId: user.id,
        planId: plan.id,
        osTemplateId: osTemplate.id,
        status: "PENDING",
      },
      select: { id: true },
    });
    parallelServers.push(s.id);
  }

  // 1 server that gets a PROVISION then a DELETE — must stay strictly ordered.
  const orderedServer = await db.server.create({
    data: {
      name: `${TEST_TAG}-ordered`,
      hostname: `${TEST_TAG}-ordered`,
      userId: user.id,
      planId: plan.id,
      osTemplateId: osTemplate.id,
      status: "PENDING",
    },
    select: { id: true },
  });

  const allServerIds = [...parallelServers, orderedServer.id];

  // Jobs: one per parallel server (should overlap), plus PROVISION+DELETE for
  // the ordered server (must never overlap, must run in creation order).
  const now = Date.now();
  const jobsToCreate = [
    ...parallelServers.map((serverId, i) => ({
      type: "BACKUP_CREATE", // arbitrary real enum value; the fake runner never dispatches on it
      status: "QUEUED",
      serverId,
      createdAt: new Date(now + i),
    })),
    { type: "PROVISION", status: "QUEUED", serverId: orderedServer.id, createdAt: new Date(now + 100) },
    { type: "DELETE", status: "QUEUED", serverId: orderedServer.id, createdAt: new Date(now + 200) },
  ];
  const createdJobs = [];
  for (const j of jobsToCreate) {
    const row = await db.job.create({ data: j, select: { id: true, type: true, serverId: true } });
    createdJobs.push(row);
  }
  console.log(`[test] seeded ${allServerIds.length} throwaway servers, ${createdJobs.length} jobs`);

  // ---- Reimplemented scheduler (mirrors worker/index.ts's main loop) -----
  const active = new Map(); // jobId -> { lockKey }
  const events = []; // { jobId, type, serverId, event: "claim"|"start"|"finish", t }
  let maxObservedConcurrency = 0;
  const CLAIM_BATCH_SIZE = Math.max(CONCURRENCY * 5, 25);

  async function fakeRunJob(job) {
    events.push({ jobId: job.id, type: job.type, serverId: job.serverId, event: "start", t: Date.now() });
    maxObservedConcurrency = Math.max(maxObservedConcurrency, active.size);
    // Simulate work — deliberately variable so ordering bugs would show up as
    // overlap rather than being hidden by lockstep timing.
    await new Promise((r) => setTimeout(r, 150 + Math.random() * 250));
    await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
    events.push({ jobId: job.id, type: job.type, serverId: job.serverId, event: "finish", t: Date.now() });
  }

  function launch(job) {
    const p = fakeRunJob(job)
      .catch((e) => console.error(`[test] job ${job.id} threw`, e))
      .finally(() => active.delete(job.id));
    active.set(job.id, { lockKey: lockKeyFor(job) });
  }

  const deadline = Date.now() + 15_000; // hard stop so a bug can't hang the test forever
  while (Date.now() < deadline) {
    // Stop once every test job has reached DONE.
    const remaining = await db.job.count({
      where: { id: { in: createdJobs.map((j) => j.id) }, status: { not: "DONE" } },
    });
    if (remaining === 0 && active.size === 0) break;

    const freeSlots = CONCURRENCY - active.size;
    let claimedThisTick = 0;
    if (freeSlots > 0) {
      const candidates = await db.job.findMany({
        where: { status: "QUEUED", id: { in: createdJobs.map((j) => j.id) } },
        orderBy: { createdAt: "asc" },
        take: CLAIM_BATCH_SIZE,
      });
      const lockedKeys = new Set();
      for (const a of active.values()) lockedKeys.add(a.lockKey);

      for (const candidate of candidates) {
        if (claimedThisTick >= freeSlots) break;
        const key = lockKeyFor(candidate);
        if (lockedKeys.has(key)) continue;
        const claim = await db.job.updateMany({
          where: { id: candidate.id, status: "QUEUED" },
          data: { status: "RUNNING", attempts: { increment: 1 } },
        });
        if (claim.count !== 1) continue;
        const claimed = await db.job.findUnique({ where: { id: candidate.id } });
        if (!claimed) continue;
        lockedKeys.add(key);
        claimedThisTick++;
        events.push({ jobId: claimed.id, type: claimed.type, serverId: claimed.serverId, event: "claim", t: Date.now() });
        launch(claimed);
      }
    }
    if (claimedThisTick === 0) await new Promise((r) => setTimeout(r, POLL_MS));
  }

  // ---- Assertions ---------------------------------------------------------
  const failures = [];

  // (a) different-server jobs actually overlapped (ran concurrently).
  if (maxObservedConcurrency < 2) {
    failures.push(`expected concurrent execution (maxObservedConcurrency>=2), got ${maxObservedConcurrency}`);
  } else {
    console.log(`[test] PASS: observed up to ${maxObservedConcurrency} jobs running concurrently (cap=${CONCURRENCY})`);
  }

  // Concurrency cap was never exceeded.
  if (maxObservedConcurrency > CONCURRENCY) {
    failures.push(`concurrency cap violated: observed ${maxObservedConcurrency} > cap ${CONCURRENCY}`);
  } else {
    console.log(`[test] PASS: concurrency cap (${CONCURRENCY}) never exceeded`);
  }

  // (b) + (c) PROVISION then DELETE on the ordered server never overlapped,
  // and DELETE only started after PROVISION finished (strict ordering).
  const provisionEvents = events.filter((e) => e.serverId === orderedServer.id && e.type === "PROVISION");
  const deleteEvents = events.filter((e) => e.serverId === orderedServer.id && e.type === "DELETE");
  const provisionStart = provisionEvents.find((e) => e.event === "start")?.t;
  const provisionFinish = provisionEvents.find((e) => e.event === "finish")?.t;
  const deleteClaim = deleteEvents.find((e) => e.event === "claim")?.t;
  const deleteStart = deleteEvents.find((e) => e.event === "start")?.t;

  if (!provisionStart || !provisionFinish || !deleteClaim || !deleteStart) {
    failures.push(`missing lifecycle events for ordered server: ${JSON.stringify({ provisionStart, provisionFinish, deleteClaim, deleteStart })}`);
  } else if (deleteClaim < provisionFinish) {
    failures.push(`DELETE was claimed (t=${deleteClaim}) BEFORE its server's PROVISION finished (t=${provisionFinish}) — ordering violated`);
  } else {
    console.log(`[test] PASS: DELETE claimed ${deleteClaim - provisionFinish}ms after PROVISION finished (never overlapped, never claimed early)`);
  }

  // Print full timeline for manual inspection.
  console.log("[test] timeline:");
  for (const e of events.sort((a, b) => a.t - b.t)) {
    console.log(`  t+${e.t - now}ms  ${e.event.padEnd(6)} ${e.type.padEnd(14)} server=${e.serverId}`);
  }

  if (failures.length) {
    console.error("[test] FAILURES:\n" + failures.map((f) => ` - ${f}`).join("\n"));
    process.exitCode = 1;
  } else {
    console.log("[test] ALL ASSERTIONS PASSED");
  }

  // ---- Cleanup --------------------------------------------------------
  await db.job.deleteMany({ where: { id: { in: createdJobs.map((j) => j.id) } } });
  await db.server.deleteMany({ where: { id: { in: allServerIds } } });
  console.log("[test] cleaned up all throwaway servers/jobs");
}

main()
  .catch((e) => {
    console.error("[test] fatal error", e);
    process.exitCode = 1;
  })
  .finally(() => db.$disconnect());

