diff --git a/worker/index.ts b/worker/index.ts
index a091af67c6..9570258228 100644
--- a/worker/index.ts
+++ b/worker/index.ts
@@ -95,6 +95,37 @@ import { deleteMinecraftSubdomainDns } from "../lib/game-subdomain-dns";
 const POLL_MS = 3000;
 const MAX_ATTEMPTS = 3;

+/**
+ * How many jobs `main()`'s loop will run concurrently. Was hardcoded to 1
+ * (fully sequential — a single slow BACKUP_CREATE could leave unrelated
+ * PROVISION jobs QUEUED for 20+ hours, confirmed against production timing
+ * data); this is the platform-wide cap on that.
+ *
+ * Deliberately modest, not unlimited, and NOT sized off Node's own CPU/event
+ * loop — almost every handler in `handlers` below is I/O-bound (a Proxmox API
+ * call + `waitForTask`, an SSH exec, a guest-agent poll), so the worker
+ * process itself is rarely the bottleneck. What actually caps this:
+ *   - Proxmox's pveproxy API is a single process per node with its own
+ *     request/worker limits, and PROVISION's clone + BACKUP_CREATE's vzdump
+ *     both saturate that node's storage I/O while they run — piling many of
+ *     those onto the SAME node at once slows every one of them down rather
+ *     than truly parallelizing (the fleet has 5 nodes, but a burst of orders
+ *     is not guaranteed to spread evenly across them).
+ *   - Each job that touches a guest opens its own SSH connection (and often
+ *     `sshpass`/child processes) via lib/ssh-exec.ts; too many concurrent
+ *     connections is connection-overhead, not throughput.
+ *   - The worker host's own CPU/RAM (see MEMORY.md's node-RAM-tuning /
+ *     disk-full-outage incidents — this primary node has hit real resource
+ *     limits before) still needs headroom for the Next.js app running
+ *     alongside it.
+ * 8 is a conservative middle ground: enough to turn a 20-order burst from
+ * ~80 minutes of pure queue wait down to a few sequential "waves" of 8, while
+ * staying well short of anything likely to rate-limit a single Proxmox node
+ * or exhaust this host's own resources. Override with WORKER_CONCURRENCY if
+ * real production behavior says otherwise.
+ */
+const WORKER_CONCURRENCY = Math.max(1, Number(process.env.WORKER_CONCURRENCY ?? 8));
+
 // Customer per-server backup retention is now the backup TIER's keep count
 // (lib/backup-tiers.ts): FREE keeps 2 (the historic default), PLUS keeps 7. Older
 // archives are pruned after every successful backup so they never pile up.
@@ -2566,6 +2597,17 @@ async function cleanupFailedProvision(serverId: string): Promise<void> {
  * Recover jobs left RUNNING by a previous worker crash/restart. Without this a
  * killed worker leaves a job RUNNING forever, which permanently blocks the
  * server's "one in-flight job" guard and strands it in a transitional state.
+ *
+ * Runs exactly once, at startup, BEFORE `main()`'s loop (and its in-process
+ * `active` map — see the concurrency comment there) starts claiming anything.
+ * That ordering matters more now than it did when the worker ran one job at a
+ * time: any row still RUNNING at this point cannot belong to a job this
+ * process is tracking (it hasn't claimed anything yet), so it can only be
+ * left over from a prior process that died mid-job — never a false positive
+ * against a legitimately-concurrent job. `findMany` + loop already handled
+ * more than one stuck row before this change (a crash could always have
+ * killed multiple in-flight jobs); nothing here needed to change for
+ * concurrency, only this note explaining why it still doesn't.
  */
 async function reapStuckJobs() {
   const stuck = await db.job.findMany({ where: { status: "RUNNING" } });
@@ -2648,6 +2690,93 @@ async function main() {
   let lastSshHealthSweep = 0;
